<?php

require_once BASE_PATH . '/includes/clients.php';

$clientId = (int)($_GET['client_id'] ?? 0);
if (!$clientId) redirect('index.php?page=clients');

$client = getClient($clientId, $_SESSION['user_id']);
if (!$client) { flash('error', 'Client not found.'); redirect('index.php?page=clients'); }

// ── AJAX: latest catalog PDF generated by this user for this client ───────
if (!empty($_GET['ajax_latest_catalog'])) {
    header('Content-Type: application/json');
    $db = getDB();
    $st = $db->prepare("
        SELECT id, name, pages, size_bytes, status, created_at
        FROM catalogs
        WHERE JSON_EXTRACT(config_json, '$._source.client_id') = ?
          AND user_id = ?
        ORDER BY created_at DESC LIMIT 1
    ");
// error_log(sprintf($clientId . $_SESSION['user_id']));
    $st->execute([$clientId, $_SESSION['user_id']]);
    echo json_encode(['catalog' => $st->fetch() ?: null]);
    exit;
}
// ── AJAX: selection history (lazy-loaded via popup — never prefetched) ─────
if (!empty($_GET['ajax_history'])) {
    require_once BASE_PATH . '/includes/selection_history.php';
    header('Content-Type: application/json');
    $hPerPage = 15;
    $hPage    = max(1, (int)($_GET['p'] ?? 1));
    $hResult  = getSelectionHistory($clientId, ['limit' => $hPerPage, 'offset' => ($hPage - 1) * $hPerPage]);
    $hTotal   = $hResult['total'];
    $hPages   = max(1, (int)ceil($hTotal / $hPerPage));
    echo json_encode([
        'success' => true,
        'rows'    => $hResult['rows'],
        'total'   => $hTotal,
        'pages'   => $hPages,
        'current' => min($hPage, $hPages),
    ]);
    exit;
}

$pageTitle = h($client['client_name']) . ' — Selections';
$showNav   = true;
$extraCSS  = ['selection_history.css'];
$extraJS   = ['selection_history.js'];

$perPage     = 10;
$currentPage = max(1, (int)($_GET['p'] ?? 1));
$search      = trim($_GET['q'] ?? '');
$isAjax      = !empty($_GET['ajax']);

$result = getSelections($clientId, $_SESSION['user_id'], [
    'search' => $search,
    'limit'  => $perPage,
    'offset' => ($currentPage - 1) * $perPage,
]);
$selections = $result['rows'];
$total      = $result['total'];
$totalPages = max(1, (int)ceil($total / $perPage));

if ($isAjax) {
    ob_start();
    include BASE_PATH . '/pages/_selection_rows.php';
    $html = ob_get_clean();
    header('Content-Type: application/json');
    echo json_encode(['html' => $html, 'total' => $total, 'pages' => $totalPages, 'current' => $currentPage]);
    exit;
}
