<script>
(function () {
  const content  = document.getElementById('selContent');
  const loader   = document.getElementById('selLoader');
  const countEl  = document.getElementById('selCount');
  const searchEl = document.getElementById('selSearch');
  const modal    = document.getElementById('editSelModal');
  const clientId = <?= $clientId ?>;

  let state = { q: <?= json_encode($search) ?>, page: 1 };
  let timer = null;

  async function load(page, push) {
    state.page = page;
    if (loader) loader.style.display = 'flex';
    const params = new URLSearchParams({ page: 'client_selections', ajax: '1', client_id: clientId, p: page });
    if (state.q) params.set('q', state.q);
    try {
      const r = await fetch('index.php?' + params);
      const d = await r.json();
      content.innerHTML = d.html;
      if (countEl) countEl.innerHTML = '<strong style="font-size:18px;color:var(--text);">' + d.total + '</strong> products selected';
      bindButtons();
    } finally {
      if (loader) loader.style.display = 'none';
    }
  }

  function bindButtons() {
    // Pagination
    content.querySelectorAll('.pag-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        if (btn.classList.contains('disabled') || btn.classList.contains('active')) return;
        load(parseInt(btn.dataset.page));
      });
    });
    // Edit buttons
    content.querySelectorAll('.sel-edit-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.getElementById('editSelId').value    = btn.dataset.id;
        document.getElementById('editSelArea').value  = btn.dataset.area  || '';
        document.getElementById('editSelQty').value   = btn.dataset.qty   || '';
        document.getElementById('editSelNotes').value = btn.dataset.notes || '';
        modal.style.display = 'flex';
      });
    });
    // Delete buttons
    content.querySelectorAll('.sel-delete-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!confirm('Remove "' + btn.dataset.name + '" from this selection?')) return;
        const form = document.createElement('form');
        form.method = 'POST'; form.action = 'index.php';
        form.innerHTML = '<input type="hidden" name="action" value="delete_selection"/>' +
          '<input type="hidden" name="selection_id" value="' + btn.dataset.id + '"/>' +
          '<input type="hidden" name="client_id" value="' + clientId + '"/>' +
          '<input type="hidden" name="csrf_token" value="<?= h(csrfToken()) ?>"/>';
        document.body.appendChild(form); form.submit();
      });
    });
  }

  // Search
  if (searchEl) {
    searchEl.addEventListener('input', () => {
      const v = searchEl.value.trim();
      clearTimeout(timer);
      if (v.length > 0 && v.length < 3) return;
      timer = setTimeout(() => { state.q = v; load(1); }, 350);
    });
  }

  // Modal close
  document.getElementById('editSelClose')?.addEventListener('click',     () => { modal.style.display = 'none'; });
  document.getElementById('editSelCancelBtn')?.addEventListener('click', () => { modal.style.display = 'none'; });
  modal?.addEventListener('click', e => { if (e.target === modal) modal.style.display = 'none'; });

  // Handle edit form submit via AJAX
  document.getElementById('editSelForm')?.addEventListener('submit', async function (e) {
    e.preventDefault();
    const body = new FormData(this);
    try {
      const r = await fetch('index.php', {
        method: 'POST',
        body,
        headers: { 'X-Requested-With': 'XMLHttpRequest' }
      });
      if (!r.ok) throw new Error('HTTP ' + r.status);
      let d = {};
      try { d = await r.json(); } catch (_) { /* non-JSON success path, ignore */ }
      if (d && d.success === false) throw new Error(d.error || 'Update failed.');
      modal.style.display = 'none';
      load(state.page, false);
    } catch (err) {
      alert('Could not save changes: ' + err.message + '. Please refresh and try again.');
    }
  });
  bindButtons();
  
  // ── Selection PDF generation ────────────────────────────────────────────
  var catalogCard  = document.getElementById('selCatalogCard');
  var catalogTitle = document.getElementById('selCatalogTitle');
  var catalogMeta  = document.getElementById('selCatalogMeta');
  var dlBtn        = document.getElementById('selCatalogDlBtn');
  var emailBtn     = document.getElementById('selCatalogEmailBtn');
  var genBtn       = document.getElementById('selGenPdfBtn');
  var latestCatalogId = null;

  function showCatalogState(state2, opts) {
    opts = opts || {};
    catalogCard.style.display = 'block';
    catalogTitle.textContent = opts.title || '';
    catalogMeta.textContent = opts.meta || '';
    if (opts.catalogId) {
      dlBtn.href = 'index.php?catalog_download=1&id=' + opts.catalogId;
      dlBtn.style.display = state2 === 'done' ? '' : 'none';
    } else {
      dlBtn.style.display = 'none';
    }
    emailBtn.style.display = state2 === 'done' ? '' : 'none';
  }

  function loadLatestCatalog() {
    fetch('index.php?page=client_selections&client_id=' + clientId + '&ajax_latest_catalog=1')
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (!d.catalog) { catalogCard.style.display = 'none'; return; }
        latestCatalogId = d.catalog.id;
        var sizeMb = d.catalog.size_bytes ? (d.catalog.size_bytes / 1048576).toFixed(1) + ' MB' : '';
        var pages  = d.catalog.pages ? d.catalog.pages + ' pages' : '';
        var when   = new Date(d.catalog.created_at * 1000).toLocaleString();
        if (d.catalog.status === 'done') {
          showCatalogState('done', { title: d.catalog.name, meta: [pages, sizeMb, when].filter(Boolean).join(' · '), catalogId: d.catalog.id });
        } else if (d.catalog.status === 'failed') {
          showCatalogState('error', { title: 'Last generation failed', meta: when });
        } else {
          showCatalogState('pending', { title: 'Generating…', meta: when });
        }
      })
      .catch(function () { catalogCard.style.display = 'none'; });
  }

  if (genBtn) {
    genBtn.addEventListener('click', function () {
      if (!confirm('Generate a PDF with all products currently in this selection?')) return;
      genBtn.disabled = true;
      var orig = genBtn.innerHTML;
      genBtn.innerHTML = '<?= icon("refresh",14) ?> Generating…';
      showCatalogState('pending', { title: 'Generating selection PDF…', meta: 'This may take a moment.' });

      var body = new URLSearchParams();
      body.set('action', 'generate_selection_pdf');
      body.set('client_id', clientId);
      body.set('csrf_token', <?= json_encode(csrfToken()) ?>);

      fetch('index.php', { method: 'POST', body: body, headers: { 'X-Requested-With': 'XMLHttpRequest' } })
        .then(function (r) { return r.json(); })
        .then(function (d) {
          if (d.success) {
            latestCatalogId = d.catalog_id;
            showCatalogState('done', {
              title: d.client_name + ' — Selections',
              meta: d.pages + ' pages · ' + (d.size / 1048576).toFixed(1) + ' MB',
              catalogId: d.catalog_id,
            });
          } else {
            showCatalogState('error', { title: 'Generation failed', meta: d.error || 'Unknown error.' });
            alert('Could not generate PDF: ' + (d.error || 'Unknown error.'));
          }
        })
        .catch(function (e) {
          showCatalogState('error', { title: 'Generation failed', meta: e.message });
          alert('Request failed: ' + e.message);
        })
        .finally(function () {
          genBtn.disabled = false;
          genBtn.innerHTML = orig;
        });
    });
  }

  // ── Email modal ──────────────────────────────────────────────────────────
  var emailModal = document.getElementById('selEmailModal');
  function openEmailModal() {
    if (!latestCatalogId) { alert('Generate a PDF first.'); return; }
    document.getElementById('selEmailTo').value = '';
    document.getElementById('selEmailCc').value = '';
    document.getElementById('selEmailBcc').value = '';
    document.getElementById('selEmailSubject').value = 'Your Product Selection Catalog';
    document.getElementById('selEmailMessage').value = 'Hi,\n\nPlease find attached your product selection catalog.\n\nRegards';
    document.getElementById('selEmailStatus').textContent = '';
    emailModal.style.display = 'flex';
  }
  function closeEmailModal() { emailModal.style.display = 'none'; }
  emailBtn && emailBtn.addEventListener('click', openEmailModal);
  document.getElementById('selEmailClose')?.addEventListener('click', closeEmailModal);
  document.getElementById('selEmailCancel')?.addEventListener('click', closeEmailModal);
  emailModal?.addEventListener('click', function (e) { if (e.target === this) closeEmailModal(); });

  document.getElementById('selEmailForm')?.addEventListener('submit', function (e) {
    e.preventDefault();
    var btn = document.getElementById('selEmailSendBtn');
    var status = document.getElementById('selEmailStatus');
    var to = document.getElementById('selEmailTo').value.trim();
    if (!to) { alert('Recipient email is required.'); return; }

    btn.disabled = true;
    status.style.color = 'var(--text3)';
    status.textContent = 'Sending…';

    var body = new URLSearchParams();
    body.set('action', 'send_selection_catalog_email');
    body.set('catalog_id', latestCatalogId);
    body.set('to', to);
    body.set('cc', document.getElementById('selEmailCc').value.trim());
    body.set('bcc', document.getElementById('selEmailBcc').value.trim());
    body.set('subject', document.getElementById('selEmailSubject').value);
    body.set('message', document.getElementById('selEmailMessage').value);
    body.set('csrf_token', <?= json_encode(csrfToken()) ?>);

    fetch('index.php', { method: 'POST', body: body, headers: { 'X-Requested-With': 'XMLHttpRequest' } })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (d.success) {
          status.style.color = 'var(--success)';
          status.textContent = 'Sent ✓';
          setTimeout(closeEmailModal, 1200);
        } else {
          status.style.color = 'var(--danger)';
          status.textContent = 'Error: ' + (d.error || 'send failed');
        }
      })
      .catch(function (e) {
        status.style.color = 'var(--danger)';
        status.textContent = 'Request failed: ' + e.message;
      })
      .finally(function () { btn.disabled = false; });
  });
 loadLatestCatalog();
})();
</script>

